-- Zone Gore Overhaul, kid mode for particles: particles\blend on the DX9 (R2) renderer.
-- Exactly the C++ particle blender (xray-monolith Blender_Particle.cpp, R2 branch) with this
-- mod list's shaders.xr settings for particles\blend (from base:files.db0): priority 3, strict sorting on,
-- blending BLEND, texture clamp on. It only exists so that effects pointed at zgo\particle_*
-- load on this renderer (a missing shader name is fatal there); kid mode hides nothing here.
-- Generated by tools/zgo_kidfx/kidfx_pe.py shaders --write; tests/zgo_test_kidfx.lua checks it.

function normal(shader, t_base, t_second, t_detail)
	shader:begin("particle", "particle")
		:sorting(3, true)
		:fog(false)
		:zb(true, false)
		:blend(true, blend.srcalpha, blend.invsrcalpha)
		:aref(true, 0)
	shader:sampler("s_base"):texture(t_base):clamp()
	shader:sampler("s_position"):texture("$user$position")
end
